// lib
using MessagePack;

namespace Lib
{
    // Compiled into a separate assembly, so its members have no DeclaringSyntaxReferences when seen from the app.
    [MessagePackObject]
    public class BaseMessage
    {
        [Key(0)]
        public int Id { get; set; }
    }
}

// app
using MessagePack;

namespace App
{
    // The first member seen (declared here) uses a string key, so isIntKey is false.
    // The inherited metadata member Lib.BaseMessage.Id then has an int key (stringKey == null),
    // which reports MsgPack005 for a member that has no syntax reference.
    [MessagePackObject]
    public class DerivedMessage : Lib.BaseMessage
    {
        [Key("name")]
        public string Name { get; set; }
    }

    public static class Program
    {
        public static void Main()
        {
            var bytes = MessagePackSerializer.Serialize(new DerivedMessage { Id = 1, Name = "x" });
            System.Console.WriteLine(bytes.Length);
        }
    }
}
